//! Holds the Rust YAML parser to `Bun.YAML` on a shared corpus (plan task 2.2). The corpus is generated by
//! `bun runner/scripts/yaml-corpus.ts` from every workflow the fixtures render, this repository's own workflows and a list
//! of tricky snippets. Each document must parse to the same data, and each pair must get the same equality verdict.
//!
//! A difference that is understood and accepted goes in `KNOWN_DIFFERENCES` with its reason. The test fails on any other
//! difference, and also when a listed one no longer differs, so the list cannot go stale.

use scaffold_core::equality::{compare_workflows, parse_yaml};
use serde_json::Value;

/// Documents (by name) where the parsers differ on purpose, and why.
const KNOWN_DIFFERENCES: &[(&str, &str)] = &[
    (
        "snippet:tab-after-colon",
        "`a:<TAB>1`: Bun accepts a tab after the colon, saphyr refuses it. YAML 1.2 allows it, but no workflow uses it, and GitHub's own parser rejects tabs.",
    ),
    (
        "snippet:large-int",
        "An integer past 2^53: Bun reads a double and prints 12345678901234567000, saphyr keeps the exact 12345678901234567168. The two numbers are the same double, only the text of a difference message changes.",
    ),
];

fn is_known(name: &str) -> bool {
    KNOWN_DIFFERENCES.iter().any(|(n, _)| *n == name)
}

fn corpus() -> Value {
    let text = include_str!("data/yaml-corpus.json");
    serde_json::from_str(text).expect("the corpus is valid JSON")
}

#[test]
fn every_document_parses_to_the_same_data_as_bun() {
    let corpus = corpus();
    let docs = corpus["docs"].as_array().unwrap();
    assert!(
        docs.len() > 100,
        "the corpus looks truncated: {} documents",
        docs.len()
    );
    let mut unexpected = Vec::new();
    let mut stale = Vec::new();
    for doc in docs {
        let name = doc["name"].as_str().unwrap();
        let text = doc["text"].as_str().unwrap();
        let ours = parse_yaml(text);
        let same = match doc.get("parsed") {
            Some(expected) => ours.as_ref().is_ok_and(|v| v == expected),
            None => ours.is_err(),
        };
        let known = is_known(name);
        match (same, known) {
            (false, false) => unexpected.push(format!(
                "{name}\n    bun:  {:?}\n    rust: {ours:?}",
                doc.get("parsed")
            )),
            (true, true) => stale.push(name.to_owned()),
            _ => {}
        }
    }
    assert!(
        unexpected.is_empty(),
        "documents that parse differently from Bun:\n  {}",
        unexpected.join("\n  ")
    );
    assert!(
        stale.is_empty(),
        "documents listed as known differences that now agree: {stale:?}"
    );
}

#[test]
fn every_pair_gets_the_same_equality_verdict_as_bun() {
    let corpus = corpus();
    let docs = corpus["docs"].as_array().unwrap();
    let text = |i: &Value| docs[i.as_u64().unwrap() as usize]["text"].as_str().unwrap();
    let name = |i: &Value| docs[i.as_u64().unwrap() as usize]["name"].as_str().unwrap();
    let mut unexpected = Vec::new();
    let mut compared = 0;
    for pair in corpus["pairs"].as_array().unwrap() {
        if is_known(name(&pair["a"])) || is_known(name(&pair["b"])) {
            continue;
        }
        compared += 1;
        let (a, b) = (text(&pair["a"]), text(&pair["b"]));
        let expected = &pair["expected"];
        let ours = compare_workflows(a, b);
        let same = if expected.get("error").is_some() {
            ours.is_err()
        } else {
            ours.as_ref().is_ok_and(|c| {
                expected["equal"] == c.equal
                    && serde_json::to_value(&c.differences).unwrap() == expected["differences"]
                    && serde_json::to_value(&c.duplicate_keys).unwrap() == expected["duplicateKeys"]
            })
        };
        if !same {
            unexpected.push(format!(
                "{} vs {}\n    bun:  {expected}\n    rust: {ours:?}",
                name(&pair["a"]),
                name(&pair["b"])
            ));
        }
    }
    assert!(compared > 150, "too few pairs were compared: {compared}");
    assert!(
        unexpected.is_empty(),
        "pairs with a different verdict from Bun:\n  {}",
        unexpected.join("\n  ")
    );
}
